routes.script:
LET $e = QUERY SELECT id FROM {{t:main}} WHERE username = {{body.username}} LIMIT 1;
IF LEN($e.rows) > 0
  RETURN 409 { "ok": false, "error": "USER_EXISTS" };
END
EXEC INSERT INTO {{t:main}} (only_id, username, password_hash, nickname) VALUES ({{onlyId}}, {{body.username}}, SM4_ENC({{body.password}}, 'clickbuild-key'), {{body.nickname}});
LET $t = TOKEN NEW { "onlyId": {{onlyId}}, "username": {{body.username}} };
RETURN 201 { "ok": true, "token": $t.token };

LET $u = QUERY SELECT only_id, password_hash FROM {{t:main}} WHERE username = {{body.username}} LIMIT 1;
IF LEN($u.rows) == 0
  RETURN 401 { "ok": false, "error": "NO_USER" };
END
IF SM4_DEC($u.rows[0].password_hash, 'clickbuild-key') != {{body.password}}
  RETURN 401 { "ok": false, "error": "BAD_PASSWORD" };
END
LET $t = TOKEN NEW { "onlyId": $u.rows[0].only_id, "username": {{body.username}} };
RETURN 200 { "ok": true, "token": $t.token };

LET $rows = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{where:main}} ORDER BY {{orderBy:main}} LIMIT {{limit}} OFFSET {{offset}};
LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $rows = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{where:main}} ORDER BY {{orderBy:main}} LIMIT {{limit}} OFFSET {{offset}};
LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $row = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($row.rows) == 0
  RETURN 404 { "ok": false, "error": "NOT_FOUND" };
END
RETURN 200 { "row": $row.rows[0] };

# 文件已经由服务器写进对象存储，这里只做入库；{{objectKey}} {{objectUrl}} {{filename}} {{size}} 都是现成的
EXEC UPDATE {{t:main}} SET {{bindColumn:main}} = {{objectKey}} WHERE {{idColumn:main}} = {{id}};
RETURN 200 { "key": {{objectKey}}, "url": {{objectUrl}}, "name": {{filename}} };

LET $v = QUERY SELECT id, title, file_key, views FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($v.rows) == 0
  RETURN 404 { "ok": false, "error": "NO_VIDEO" };
END
EXEC UPDATE {{t:main}} SET views = views + 1 WHERE {{idColumn:main}} = {{id}};
RETURN 200 { "ok": true, "video": $v.rows[0] };

LET $e = QUERY SELECT id FROM {{t:main}} WHERE video_id = {{body.video_id}} AND user_only_id = {{user.onlyId}} LIMIT 1;
IF LEN($e.rows) > 0
  EXEC DELETE FROM {{t:main}} WHERE id = $e.rows[0].id;
  RETURN 200 { "ok": true, "favorited": false };
END
EXEC INSERT INTO {{t:main}} (video_id, user_only_id) VALUES ({{body.video_id}}, {{user.onlyId}});
RETURN 200 { "ok": true, "favorited": true };
